 */

//#region src/components/MultiSelect/filter.ts
/**
* Copyright IBM Corp. 2016, 2025
*
* This source code is licensed under the Apache-2.0 license found in the
* LICENSE file in the root directory of this source tree.
*/
const defaultFilterItems = (items, { itemToString, inputValue }) => {
	if (!inputValue) return items;
	const normalizedInput = inputValue.toLowerCase();
	return items.filter((item) => itemToString(item).toLowerCase().includes(normalizedInput));
};
//#endregion
export { defaultFilterItems };
